import{_ as e}from"./chunks/notifikace_okno.BKxbiXUu.js";import{_ as i}from"./chunks/en_nastaveni_notifikace.DJ-aaAt_.js";import{_ as a,o,c as n,aa as s}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/cs/firstofall/btn_notification.png",_=JSON.parse('{"title":"Notification System","description":"","frontmatter":{"title":"Notification System","wiki":"en:tickets:notification"},"headers":[],"relativePath":"en/tickets/notification.md","filePath":"en/tickets/notification.md","lastUpdated":1794388980000}'),c={name:"en/tickets/notification.md"};function l(h,t,p,d,m,f){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="notification-system" tabindex="-1">Notification System <a class="header-anchor" href="#notification-system" aria-label="Permalink to &quot;Notification System&quot;">​</a></h1><p>The application monitors all changes made by individual users to tickets. It then sends notifications about these changes to users who are in some way associated with the ticket.</p><h2 id="in-app-notifications" tabindex="-1">In-App Notifications <a class="header-anchor" href="#in-app-notifications" aria-label="Permalink to &quot;In-App Notifications&quot;">​</a></h2><figure class="shot" style="--w:350px;"><img src="'+e+'" alt="Notification Window" width="330" loading="lazy"></figure><p>The application uses the <img src="'+r+'" alt="Bell" data-no-zoom loading="lazy"> icon in the top bar to notify users about changes to tickets.</p><p>If there is a <strong>number in a red box</strong> next to the icon, it means that a change has been made to one of the tickets by another user. Clicking the icon allows the user to view the notification and, if applicable, open the relevant ticket.</p><p>Notifications are displayed to the ticket author, assignees, and approvers, except for the user who made the change.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The bell icon is also used by the application when a signature attempt for a record in the Project Diary module fails. Therefore, a notification may contain not only information about a ticket change, but also the reason why a Project Diary record could not be signed.</p></div><h2 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h2><figure class="shot" style="--w:350px;"><img src="'+i+'" alt="Notification Settings for a Project Team Member" width="330" loading="lazy"></figure><p>Each Project Team member can also receive email notifications about new tickets and changes. This option must first be enabled in <strong>Project Settings (Project Team → Project Team Members - Edit Member)</strong>.</p><p><strong>The default setting is &quot;None&quot;</strong>, meaning that no notifications are sent.</p><p><strong>There are three options to choose from:</strong></p><p><strong>HTML Email</strong> ⇒ users with this setting will receive notifications about a new ticket when they are assigned as an assignee or approver, as well as about new posts in the Discussion or Statements.</p><p><strong>Email with Event</strong> ⇒ users with this setting will receive notifications when a new ticket is created, a ticket is deleted, or the planned end date is changed. The event is also added to the calendar on the planned end date.</p><p><strong>Summary Email</strong> ⇒ users with this setting will receive one email per day summarizing changes to tickets they are involved in.</p>',16)])])}const w=a(c,[["render",l]]);export{_ as __pageData,w as default};
